"""Exclusive offline correction of two independent review findings."""
from pathlib import Path
import json,hashlib,re
R=Path.cwd();H=Path(__file__).resolve().parent;D=H.parent.parent;report=D/'S5-CRASH-FALLBACK-OBSERVER-TEST-PREPARATION.md';plan=R/'docs/superpowers/plans/2026-10-13-crash-fallback-observer-test-integration.md';old=(H/'append.jl').read_text();prefix=(H/'original-test.jl').read_bytes()
def put(p,b):
 with p.open('xb') as f:f.write(b if isinstance(b,bytes) else b.encode())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
assert (H/'review.md').exists()
put(H/'review-initial.md',(H/'review.md').read_bytes())
for p in [report,plan]:put(H/(p.name+'.before-review'),p.read_bytes())
insert='using LinearAlgebra: SingularException\n\n';pos=old.index('mutable struct CrashFallbackObserverProbe');new=old[:pos]+insert+old[pos:];cand=prefix+new.encode();h=hashlib.sha256(cand).hexdigest()
